const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function load(){const el=document.getElementById('actual');try{const r=await fetch('/project.json');if(!r.ok)throw Error();const p=await r.json();if(p.error){el.textContent=p.error;return}document.title=p.name+' · .agents · 实际工程';el.innerHTML=`<header class="page-heading"><div><h1>${esc(p.name)}</h1><p>实际工程接入评估 · 只读 · ${esc(new Date(p.checkedAt).toLocaleString())}</p></div><button id="refresh">重新读取</button></header><div class="feedback"><strong>这里读取你的工程，不使用演示配置</strong><p>现在可以核对配置来源、字段是否已设置和插件状态。所有值均留在后端，不返回密码、Key、地址或账号；不执行安装、保存或远端测试。</p></div><h2>现在能做什么，还不能做什么</h2><div class="table-wrap"><table><tr><th>能力</th><th>现在</th><th>接入后可承担的工作 / 当前缺口</th></tr>${[['工程配置 / 连接 / Key','真实只读','发现已有字段及空项；保存仍缺 owner 合并、冲突检查、加密与读回验证。'],['插件','读取 profile 状态','安装、启停必须接 plugin-deploy 与依赖检查；默认基础能力不由 UI 停用。'],['MCP / 客户端','读取 MCP 字段','程序存在、宿主加载、工具发现和认证均未验证；配置存在不等于可用。'],['知识与向量','读取提供方配置','资料检索、索引状态、构建续建尚未接通；读取不发起 Embedding 请求。'],['部署 / 更新 / 备份','尚未接通执行','可由框架入口实现；需要任务回执、影响预览与恢复适配。'],['工程探索 / 语义配置','需要 Agent 判断','UI 可展示来源和交接目标，不能自行判断业务事实；宿主自动派发接口未验证。']].map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')}</table></div><h2>实际配置覆盖</h2><p class="muted">展开可查看真实字段清单；“已设置”仅表示有值，不表示有效或认证成功。</p>${p.domains.map(d=>`<details class="config-section"><summary><strong>${esc(d.name)}</strong> · ${esc(d.scope)} · ${esc(d.status)} · ${d.fields.length} 个字段</summary><p class="field-help">来源：${esc(d.source)}${d.scope.includes('共享')?'；修改会影响所有引用该来源的工程，目前只读。':''}</p><div class="table-wrap"><table><tr><th>配置字段</th><th>设置状态</th><th>编辑边界</th></tr>${d.fields.map(f=>`<tr><td>${esc(f.key)}</td><td>${esc(f.status)}</td><td>${f.sensitive?'凭据：未来支持保留 / 替换 / 清除':'字段级更新待接入'} · 当前只读</td></tr>`).join('')}</table></div></details>`).join('')}<h2>工程插件与领域配置</h2><section class="config-section"><h3>plugin_profile.md 的明确状态</h3>${p.plugins.length?'<div class="table-wrap"><table>'+p.plugins.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.status)}</td></tr>`).join('')+'</table></div>':'<p>未解析出明确状态行，不能据此判断插件未安装或未启用。</p>'}${p.profiles.map(x=>`<p>${esc(x.name)} · ${x.exists?'文件存在，语义仍需 owner / Agent 核对':'未发现'}</p>`).join('')}</section><p class="footer">真实只读识别与原交互演示相互独立。此页无配置写接口。</p>`;document.getElementById('refresh').onclick=load}catch{el.innerHTML='<h1>实际工程读取失败</h1><p>请检查本地服务是否正在运行，工程文件未被修改。</p><button id="retry">重新读取</button>';document.getElementById('retry').onclick=load}}load();
